from __future__ import annotations

import reflex as rx

from .looks.canvas import canvas_page
from .looks.hybrid import hybrid_page
from .looks.shelf import shelf_page
from .looks.split import split_page
from .looks.thread import thread_page
from .looks.tui import tui_page
from .looks.widgets import widgets_page
from .looks.zed import zed_page

DESCRIPTIONS = {
    "tui": "Pure TUI twin: all monospace, character grid, footer of key hints.",
    "hybrid": "Hybrid: Zed-style chrome around TUI-style cells, rich web output.",
    "zed": "Full Zed-like: dock, tab bar, one continuous buffer with a gutter.",
    "widgets": "Hybrid plus interactive widgets: sortable data viewer, chart tab.",
    "thread": "AI-first: one conversation; tool output becomes a widget, Python is another message.",
    "split": "AI-first: chat on the left, data workspace and Python console on the right.",
    "shelf": "AI-first: data objects on a shelf; pick one, inspect it, act on it.",
    "canvas": "AI-first: question, tool call, widgets and Python as wired nodes.",
}


def index() -> rx.Component:
    return rx.el.div(
        rx.el.div(
            rx.el.h1("design_poc: look mockups", class_name="sans"),
            *[
                rx.el.a(rx.el.span(f"/{look}", class_name="mono"), rx.el.span(text, class_name="dim"), href=f"/{look}")
                for look, text in DESCRIPTIONS.items()
            ],
            class_name="index sans",
        ),
        class_name="page",
    )


# theme=None: no Radix theme wrapper, all styling comes from assets/everforest.css.
app = rx.App(theme=None, stylesheets=["/everforest.css"])
app.add_page(index, route="/", title="design_poc looks")
app.add_page(tui_page, route="/tui", title="look: tui")
app.add_page(hybrid_page, route="/hybrid", title="look: hybrid")
app.add_page(zed_page, route="/zed", title="look: zed")
app.add_page(widgets_page, route="/widgets", title="look: widgets")
app.add_page(thread_page, route="/thread", title="look: thread")
app.add_page(split_page, route="/split", title="look: split")
app.add_page(shelf_page, route="/shelf", title="look: shelf")
app.add_page(canvas_page, route="/canvas", title="look: canvas")
